//! Shared `serde` helpers for parsing model-supplied tool arguments.

use std::str::FromStr;

use serde::{Deserialize, Deserializer};
use uuid::Uuid;

/// Deserializes an optional string field and parses it into an Uuid, doing this
/// optionally without failure. If an error occurs, a None is returned. This is
/// desired for truly optional id fields generated by an LLM, which can be None or
/// a non-Uuid string in some cases. If any errors should occur, they are emitted
/// in ChatbotTools's from_db_and_arguments.
pub fn deserialize_to_optional_uuid_and_errors_to_none<'de, D>(
    deserializer: D,
) -> Result<Option<Uuid>, D::Error>
where
    D: Deserializer<'de>,
{
    let res = String::deserialize(deserializer)
        .ok()
        .and_then(|s| Uuid::from_str(&s).ok());
    Ok(res)
}
